 SetupISM(Particles,Preset==4?TEXT("/Engine/BasicShapes/Sphere.Sphere"):Cube,Preset==4?TEXT("/Game/KTW/Materials/M_SnowWhite.M_SnowWhite"):TEXT("/Game/KTW/Materials/M_RainBlue.M_RainBlue"));SetupISM(WetRoads,Cube,TEXT("/Game/KTW/Materials/M_WetStreet.M_WetStreet"));SetupISM(SnowRoofs,Cube,TEXT("/Game/KTW/Materials/M_SnowWhite.M_SnowWhite"));SetupISM(Lamps,Cube,TEXT("/Game/KTW/Materials/M_NeonBlue.M_NeonBlue"));Particles->ClearInstances();WetRoads->ClearInstances();SnowRoofs->ClearInstances();Lamps->ClearInstances();Drops.Empty();for(UPointLightComponent* L:Neon)if(L)L->DestroyComponent();Neon.Empty();
